begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(1);
create function pg_temp.assert_directory(v boolean,msg text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Directory assertion: %',msg;end if;end $$;
create function pg_temp.deny_directory(statement text,msg text) returns void language plpgsql as $$begin begin execute statement;exception when others then return;end;raise exception 'Expected denial: %',msg;end $$;
-- Fixtures are transaction-only; no dummy identity is committed.
insert into public.branches(code,name) values('ARQ','[CONTOH] Archive other branch');
insert into auth.users(id,email) select ('ac110000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'directory.qa.'||i||'@example.invalid' from generate_series(1,5)i;
insert into public.employee_directory(id,branch_code,full_name,npp) select ('ac220000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=5 then 'ARQ' else 'DPS' end,'[CONTOH] Directory QA '||i,case when i=6 then null else '0088'||i end from generate_series(1,6)i;
insert into public.profiles(id,employee_id,branch_code,full_name,is_active) select ('ac110000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,('ac220000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=5 then 'ARQ' else 'DPS' end,'[CONTOH] Directory account '||i,true from generate_series(1,5)i;
insert into public.user_role_assignments(profile_id,branch_code,role_code,grant_reason) select ('ac110000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=5 then 'ARQ' else 'DPS' end,(array['super_admin','hrga','admin','inspector','super_admin'])[i],'[CONTOH] Transaction-only directory regression' from generate_series(1,5)i;
select set_config('request.jwt.claim.sub','ac110000-0000-4000-8000-000000000001',true);
insert into public.portfolios(id,branch_code,code,name) values('ac330000-0000-4000-8000-000000000001','DPS','CONTOH_ARCH_QA','[CONTOH] Archive QA');
insert into public.certificate_types(id,branch_code,code,name,category) values('ac440000-0000-4000-8000-000000000001','DPS','CONTOH_ARCH_QA','[CONTOH] Archive license','personnel');
insert into public.personnel_certificates(id,employee_id,branch_code,certificate_type_id,original_title,verification_status) values('ac550000-0000-4000-8000-000000000001','ac220000-0000-4000-8000-000000000006','DPS','ac440000-0000-4000-8000-000000000001','[CONTOH] Certificate kept','pending');
insert into public.equipment(id,branch_code,portfolio_id,name,responsible_employee_id,responsibility_override_reason) values('ac660000-0000-4000-8000-000000000001','DPS','ac330000-0000-4000-8000-000000000001','[CONTOH] Historical equipment','ac220000-0000-4000-8000-000000000006','[CONTOH] Reviewed historical responsibility');
select set_config('request.jwt.claim.sub','ac110000-0000-4000-8000-000000000001',true);
set local role authenticated;
select public.manage_employee_directory('ac220000-0000-4000-8000-000000000006','DPS','verify','[CONTOH] Name compared to approved master',(select updated_at from public.employee_directory where id='ac220000-0000-4000-8000-000000000006'));
select pg_temp.assert_directory((select verification_status='verified' and verified_by=auth.uid() and not is_active and npp is null from public.employee_directory where id='ac220000-0000-4000-8000-000000000006'),'verification metadata without activation or fabricated NPP');
select public.manage_employee_directory('ac220000-0000-4000-8000-000000000006','DPS','archive','[CONTOH] Reviewed redundant directory entry',(select updated_at from public.employee_directory where id='ac220000-0000-4000-8000-000000000006'));
select pg_temp.assert_directory(not exists(select 1 from public.employee_directory_records where id='ac220000-0000-4000-8000-000000000006'),'hidden from active directory');
select pg_temp.assert_directory((select archived_by=auth.uid() and full_name='[CONTOH] Directory QA 6' from public.employee_directory where id='ac220000-0000-4000-8000-000000000006'),'underlying identity retained');
select pg_temp.assert_directory((select employee_id='ac220000-0000-4000-8000-000000000006' and verification_status='pending' from public.personnel_certificates where id='ac550000-0000-4000-8000-000000000001'),'certificate FK and verification preserved');
select pg_temp.assert_directory((select responsible_employee_id='ac220000-0000-4000-8000-000000000006' from public.equipment where id='ac660000-0000-4000-8000-000000000001'),'equipment FK preserved');
select pg_temp.deny_directory($q$select public.manage_employee_directory('ac220000-0000-4000-8000-000000000006','DPS','restore','[CONTOH] stale token',now()-interval '1 second')$q$,'stale update blocked');
select public.manage_employee_directory('ac220000-0000-4000-8000-000000000006','DPS','restore','[CONTOH] Reviewed restoration',(select updated_at from public.employee_directory where id='ac220000-0000-4000-8000-000000000006'));
select pg_temp.assert_directory(exists(select 1 from public.employee_directory_records where id='ac220000-0000-4000-8000-000000000006'),'restored to directory');
select pg_temp.assert_directory((select count(*)>=3 from public.audit_logs where record_id='ac220000-0000-4000-8000-000000000006' and table_name='employee_directory'),'audit history kept');
select pg_temp.deny_directory($q$select public.manage_employee_directory('ac220000-0000-4000-8000-000000000002','DPS','archive','[CONTOH] active login protected',(select updated_at from public.employee_directory where id='ac220000-0000-4000-8000-000000000002'))$q$,'active account protected');
select pg_temp.deny_directory($q$select public.manage_employee_directory('ac220000-0000-4000-8000-000000000001','DPS','archive','[CONTOH] self archive denied',(select updated_at from public.employee_directory where id='ac220000-0000-4000-8000-000000000001'))$q$,'self archive protected');
select pg_temp.deny_directory($q$select public.manage_employee_directory('ac220000-0000-4000-8000-000000000006','DPS','archive','x',(select updated_at from public.employee_directory where id='ac220000-0000-4000-8000-000000000006'))$q$,'reason required');
select set_config('request.jwt.claim.sub','ac110000-0000-4000-8000-000000000002',true);
select pg_temp.deny_directory($q$select public.manage_employee_directory('ac220000-0000-4000-8000-000000000006','DPS','archive','[CONTOH] HRGA denied',now())$q$,'HRGA cannot call management RPC');
select pg_temp.deny_directory($q$update public.employee_directory set archived_at=now(),archive_reason='[CONTOH] direct REST bypass denied' where id='ac220000-0000-4000-8000-000000000006'$q$,'direct REST archive guard');
select set_config('request.jwt.claim.sub','ac110000-0000-4000-8000-000000000003',true);
select pg_temp.deny_directory($q$select public.manage_employee_directory('ac220000-0000-4000-8000-000000000006','DPS','verify','[CONTOH] ordinary admin denied',now())$q$,'ordinary admin is not IT Officer');
select set_config('request.jwt.claim.sub','ac110000-0000-4000-8000-000000000005',true);
select pg_temp.deny_directory($q$select public.manage_employee_directory('ac220000-0000-4000-8000-000000000006','DPS','archive','[CONTOH] wrong branch denied',now())$q$,'cross branch denied');
reset role;
select pass('IT-only directory archive/restore/verification, active account protection, audit, branch RLS and preserved certificate/equipment links');
select * from finish();
rollback;
